/**
 * pyrepr.mjs — emulation of CPython's `repr()` for the value shapes this port needs.
 *
 * The reference program prints `print(decoded)`, which renders a `dict` through
 * CPython's `dict_repr` -> `PyObject_Repr` on every key/value. Reproducing that
 * byte-for-byte means reproducing `unicode_repr()` (Objects/unicodeobject.c) and
 * `float_repr` / `long_repr` exactly.
 *
 * Zero dependencies on purpose: this module imports nothing at all, so it can be
 * pulled in from anywhere in the library without risking an import cycle.
 */

/* ------------------------------------------------------------------ *
 * Printability (CPython `Py_UNICODE_ISPRINTABLE`)
 * ------------------------------------------------------------------ */

/**
 * A code point is *non*-printable when its Unicode general category is one of
 * Cc, Cf, Cs, Co, Cn, Zl, Zp, Zs. CPython carves out exactly one exception:
 * ASCII space U+0020 (a Zs) is considered printable.
 *
 * The regexp is built once, lazily, and cached. Unicode property escapes are
 * available on every modern engine (verified on the Node 18 used here), but if
 * a category escape were ever rejected we fall back to a static range table
 * instead of throwing while the module is being evaluated.
 */
const NON_PRINTABLE_PATTERN =
  '^[\\p{Cc}\\p{Cf}\\p{Cs}\\p{Co}\\p{Cn}\\p{Zl}\\p{Zp}\\p{Zs}]$';

/** @type {RegExp | null} */
let nonPrintableRe = null;
/** True once we have attempted to build the regexp (successfully or not). */
let nonPrintableReReady = false;

/**
 * Best-effort fallback ranges, used only when Unicode property escapes are
 * unavailable. Each entry is an inclusive [start, end] code point range whose
 * members are non-printable (ASCII space is filtered out before we get here).
 */
const FALLBACK_NON_PRINTABLE_RANGES = [
  [0x0000, 0x001f], // Cc
  [0x007f, 0x00a0], // Cc (DEL, C1 controls) + NBSP (Zs)
  [0x00ad, 0x00ad], // SOFT HYPHEN (Cf)
  [0x0600, 0x0605], // Cf
  [0x061c, 0x061c], // Cf
  [0x06dd, 0x06dd], // Cf
  [0x070f, 0x070f], // Cf
  [0x0890, 0x0891], // Cf
  [0x08e2, 0x08e2], // Cf
  [0x1680, 0x1680], // OGHAM SPACE MARK (Zs)
  [0x180e, 0x180f], // Cf
  [0x2000, 0x200f], // Zs + Cf
  [0x2028, 0x202f], // Zl, Zp, Cf, Zs
  [0x205f, 0x206f], // Zs + Cf (+ unassigned U+2065)
  [0x3000, 0x3000], // IDEOGRAPHIC SPACE (Zs)
  [0xd800, 0xf8ff], // Cs (surrogates) + Co (BMP private use)
  [0xfeff, 0xfeff], // ZERO WIDTH NO-BREAK SPACE (Cf)
  [0xfff9, 0xfffb], // Cf
  [0x110bd, 0x110bd], // Cf
  [0x110cd, 0x110cd], // Cf
  [0x13430, 0x1343f], // Cf
  [0x1bca0, 0x1bca3], // Cf
  [0x1d173, 0x1d17a], // Cf
  [0xe0000, 0xe0fff], // Cf (tags) + unassigned
  [0xf0000, 0x10ffff], // Co (supplementary private use planes)
];

/** Build (once) the cached non-printable matcher. */
function getNonPrintableRe() {
  if (!nonPrintableReReady) {
    nonPrintableReReady = true;
    try {
      nonPrintableRe = new RegExp(NON_PRINTABLE_PATTERN, 'u');
    } catch {
      // Unicode property escapes unsupported: stay on the range table.
      nonPrintableRe = null;
    }
  }
  return nonPrintableRe;
}

/** Range-table lookup used when no property-escape regexp is available. */
function isNonPrintableByRanges(codePoint) {
  for (const [start, end] of FALLBACK_NON_PRINTABLE_RANGES) {
    if (codePoint >= start && codePoint <= end) return true;
  }
  return false;
}

/**
 * Printability test for a single code point, expressed as its one-code-point
 * string (which is also how lone surrogates reach us).
 */
function isPrintableChar(ch, codePoint) {
  // Fast path for ASCII: printable is exactly U+0020..U+007E.
  if (codePoint < 0x80) return codePoint >= 0x20 && codePoint !== 0x7f;
  const re = getNonPrintableRe();
  if (re !== null) return !re.test(ch);
  return !isNonPrintableByRanges(codePoint);
}

/**
 * Python `str.isprintable()`.
 *
 * Named `codePointString` because `pyReprString` calls it per code point, but it
 * accepts any string and mirrors Python's semantics for one: every code point
 * must be printable (the empty string is printable).
 *
 * @param {string} codePointString
 * @returns {boolean}
 */
export function pyIsPrintable(codePointString) {
  const s = typeof codePointString === 'string' ? codePointString : String(codePointString);
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (!isPrintableChar(ch, cp)) return false;
  }
  return true;
}

/* ------------------------------------------------------------------ *
 * String repr (CPython `unicode_repr`)
 * ------------------------------------------------------------------ */

/** Lowercase, zero-padded hex — CPython uses `Py_hexdigits` (lowercase). */
function hex(codePoint, width) {
  return codePoint.toString(16).padStart(width, '0');
}

/**
 * Python `repr()` of a `str`.
 *
 * Quote selection follows CPython: single quotes normally; double quotes when
 * the string contains a `'` and no `"`; when it contains both, single quotes are
 * kept and each `'` is backslash-escaped.
 *
 * @param {string} str
 * @returns {string}
 */
export function pyReprString(str) {
  const s = typeof str === 'string' ? str : String(str);

  const hasSingle = s.indexOf("'") !== -1;
  const hasDouble = s.indexOf('"') !== -1;
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);

    // The enclosing quote and the backslash are always escaped.
    if (ch === quote || cp === 0x5c) {
      out += '\\' + ch;
      continue;
    }
    // Special-cased whitespace escapes.
    if (cp === 0x09) {
      out += '\\t';
      continue;
    }
    if (cp === 0x0a) {
      out += '\\n';
      continue;
    }
    if (cp === 0x0d) {
      out += '\\r';
      continue;
    }
    // Non-printable US-ASCII (C0 controls and DEL) -> \xhh.
    if (cp < 0x20 || cp === 0x7f) {
      out += '\\x' + hex(cp, 2);
      continue;
    }
    // Remaining ASCII is copied verbatim.
    if (cp < 0x7f) {
      out += ch;
      continue;
    }
    // Non-ASCII: printable code points stay raw, everything else is escaped.
    if (isPrintableChar(ch, cp)) {
      out += ch;
    } else if (cp <= 0xff) {
      out += '\\x' + hex(cp, 2);
    } else if (cp <= 0xffff) {
      out += '\\u' + hex(cp, 4);
    } else {
      out += '\\U' + hex(cp, 8);
    }
  }
  return out + quote;
}

/* ------------------------------------------------------------------ *
 * Numbers
 * ------------------------------------------------------------------ */

/** Python `int` repr: plain decimal digits, never exponential. */
function pyIntRepr(value) {
  // Beyond 1e21 `Number#toString` switches to exponent form; BigInt does not.
  if (Number.isFinite(value) && (value >= 1e21 || value <= -1e21)) {
    return BigInt(value).toString();
  }
  return String(value);
}

/**
 * Python `float` repr: shortest string that round-trips, always carrying a `.`
 * or an exponent, exponential form when `decpt <= -4 || decpt > 16`, and an
 * exponent padded to at least two digits (`1e-05`, not `1e-5`).
 */
function pyFloatRepr(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';

  const negative = value < 0 || Object.is(value, -0);
  const sign = negative ? '-' : '';
  const magnitude = Math.abs(value);
  if (magnitude === 0) return sign + '0.0';

  // `toExponential()` with no argument yields the shortest round-tripping
  // mantissa, i.e. exactly the digit string CPython's dtoa produces.
  const parts = magnitude.toExponential().split('e');
  const digits = parts[0].replace('.', '');
  const decpt = Number(parts[1]) + 1; // value === 0.<digits> * 10**decpt

  if (decpt <= -4 || decpt > 16) {
    const exponent = decpt - 1;
    const expSign = exponent < 0 ? '-' : '+';
    const expDigits = String(Math.abs(exponent)).padStart(2, '0');
    const mantissa = digits.length > 1 ? digits[0] + '.' + digits.slice(1) : digits;
    return sign + mantissa + 'e' + expSign + expDigits;
  }
  if (decpt <= 0) {
    return sign + '0.' + '0'.repeat(-decpt) + digits;
  }
  if (decpt >= digits.length) {
    return sign + digits + '0'.repeat(decpt - digits.length) + '.0';
  }
  return sign + digits.slice(0, decpt) + '.' + digits.slice(decpt);
}

/**
 * Recognise a value that has been explicitly tagged as a Python float so that
 * `1.0` does not collapse to `1`. Boxed `Number` objects and a handful of
 * plain-object tag shapes are accepted; primitives are classified by value.
 *
 * @returns {{ isFloat: boolean, value: number } | null}
 */
function unwrapTaggedNumber(value) {
  if (value instanceof Number) {
    return { isFloat: true, value: value.valueOf() };
  }
  if (typeof value === 'object' && value !== null) {
    const inner = typeof value.value === 'number' ? value.value : null;
    if (inner === null) return null;
    if (value.__pyFloat === true || value.pyType === 'float' || value.isFloat === true) {
      return { isFloat: true, value: inner };
    }
    if (value.__pyInt === true || value.pyType === 'int' || value.isInteger === true) {
      return { isFloat: false, value: inner };
    }
  }
  return null;
}

/** Untagged numeric primitive: integral values render as `int`, others as `float`. */
function pyNumberRepr(value) {
  if (Number.isInteger(value) && !Object.is(value, -0)) return pyIntRepr(value);
  return pyFloatRepr(value);
}

/* ------------------------------------------------------------------ *
 * Containers
 * ------------------------------------------------------------------ */

/** Render `[[key, value], ...]` pairs as a Python dict literal. */
function pyDictRepr(entries) {
  const items = [];
  for (const [key, val] of entries) {
    items.push(pyRepr(key) + ': ' + pyRepr(val));
  }
  return '{' + items.join(', ') + '}';
}

/* ------------------------------------------------------------------ *
 * Public entry point
 * ------------------------------------------------------------------ */

/**
 * Python `repr()` for the value shapes produced by this port's JSON parser.
 *
 * Mappings arrive as `Map` instances (insertion order preserved, which a plain
 * JS object would destroy for integer-like keys) and are rendered as dicts.
 *
 * @param {unknown} value
 * @returns {string}
 */
export function pyRepr(value) {
  if (value === null || value === undefined) return 'None';

  switch (typeof value) {
    case 'boolean':
      return value ? 'True' : 'False';
    case 'string':
      return pyReprString(value);
    case 'number':
      return pyNumberRepr(value);
    case 'bigint':
      return value.toString();
    default:
      break;
  }

  if (value instanceof Map) return pyDictRepr(value.entries());
  if (Array.isArray(value)) return '[' + value.map((item) => pyRepr(item)).join(', ') + ']';

  if (value instanceof Set) {
    if (value.size === 0) return 'set()';
    return '{' + [...value].map((item) => pyRepr(item)).join(', ') + '}';
  }

  if (value instanceof String) return pyReprString(value.valueOf());
  if (value instanceof Boolean) return value.valueOf() ? 'True' : 'False';

  const tagged = unwrapTaggedNumber(value);
  if (tagged !== null) {
    return tagged.isFloat ? pyFloatRepr(tagged.value) : pyIntRepr(tagged.value);
  }

  if (typeof value === 'object') return pyDictRepr(Object.entries(value));

  return String(value);
}

