// Deterministic random corpus: exercises printability across the whole code
// point space, which is where Node's Unicode tables could disagree with the
// Python build's. Seeded so emit/expect generate identical strings.
function makeRng(seed) {
  let s = seed >>> 0;
  return function next() {
    s ^= s << 13; s >>>= 0;
    s ^= s >>> 17;
    s ^= s << 5; s >>>= 0;
    return s / 4294967296;
  };
}

export function buildFuzzCases(seed, count) {
  const rnd = makeRng(seed);
  const cases = [];
  for (let i = 0; i < count; i++) {
    const len = 1 + Math.floor(rnd() * 12);
    let s = 'f' + i + '_';
    for (let j = 0; j < len; j++) {
      let cp;
      const bucket = rnd();
      if (bucket < 0.25) {
        cp = 0x20 + Math.floor(rnd() * 0x5f); // printable ASCII
      } else if (bucket < 0.5) {
        cp = Math.floor(rnd() * 0x500); // latin/greek/cyrillic/hebrew/arabic
      } else if (bucket < 0.8) {
        cp = Math.floor(rnd() * 0x10000); // whole BMP incl. surrogate range
      } else {
        cp = 0x10000 + Math.floor(rnd() * 0x100000); // astral planes
      }
      // Lone surrogates cannot survive an argv round trip through UTF-8, and a
      // NUL cannot be passed via argv at all; skip both.
      if (cp === 0 || (cp >= 0xd800 && cp <= 0xdfff)) cp = 0x41;
      s += String.fromCodePoint(cp);
    }
    cases.push(s);
  }
  return cases;
}

